/// Nested `cycle-tracker-report` scopes inside the checker, for the guest's
/// finer cycle attribution (feature `scopes`, which the guest enables; a
/// no-op everywhere else).  The names are dotted under the guest's five
/// top-level phases: `merkle.table`, `merkle.plan`, `merkle.auth`,
/// `merkle.decode`.
#[macro_export]
macro_rules! scope_start {
    ($name:literal) => {
        #[cfg(feature = "scopes")]
        println!(concat!("cycle-tracker-report-start: ", $name));
    };
}

/// See [`scope_start!`].
#[macro_export]
macro_rules! scope_end {
    ($name:literal) => {
        #[cfg(feature = "scopes")]
        println!(concat!("cycle-tracker-report-end: ", $name));
    };
}
