/// The public values the guest commits: `sha256(statement bytes) || verdict`.
pub const PUBLIC_VALUES_LEN: usize = 33;

/// The public values when the prover also supplies a **typed object digest**
/// (the `typed-obligation/v0` object digest `h_O` the statement was lowered
/// from): `h_O || sha256(statement bytes) || verdict`, i.e. `(h_O, h_L,
/// verdict)`.  The guest carries `h_O` through *unchecked*: it does not
/// validate the typed object nor prove that `h_L` is its lowering -- that
/// seam's semantics are the verifier's ([`binding::check_binding`], IR §I,
/// GUIDANCE §17), which consumes what is exposed here.  Absent a supplied
/// digest the layout is the 33-byte one above, unchanged.
pub const PUBLIC_VALUES_WITH_OBJECT_LEN: usize = 65;

/// Whether this build skips any part of the authentication (an `unsound-*` feature is on).
pub const UNSOUND: bool = cfg!(any(
    feature = "unsound-skip-authentication",
    feature = "unsound-skip-path-fold", feature = "unsound-relation-only" // (line count kept: the sound ELF)
));

/// What a diagnostic build prints before anything else; `None` for a sound build.
pub const DIAGNOSTIC_BANNER: Option<&str> = if cfg!(feature = "unsound-skip-authentication") {
    Some("UNSOUND DIAGNOSTIC BUILD: authentication skipped")
} else if cfg!(feature = "unsound-skip-path-fold") {
    Some("UNSOUND DIAGNOSTIC BUILD: path folding skipped")
} else if cfg!(feature = "unsound-relation-only") {
    Some("UNSOUND DIAGNOSTIC BUILD: relation only (no statement, no openings, no authentication)")
} else { None };

/// The verdict byte for an accepted batch: `1`, or `0xEE` in a diagnostic build.
pub const VERDICT_ACCEPT: u8 = if UNSOUND { 0xEE } else { 1 };
/// The verdict byte for a rejected batch: `0`, or `0xEF` in a diagnostic build.
pub const VERDICT_REJECT: u8 = if UNSOUND { 0xEF } else { 0 };

/// Lay out the public values for a statement digest and a verdict.
pub fn public_values(statement_digest: &[u8; 32], verdict: bool) -> [u8; PUBLIC_VALUES_LEN] {
    let mut out = [0u8; PUBLIC_VALUES_LEN];
    out[..32].copy_from_slice(statement_digest);
    out[32] = if verdict {
        VERDICT_ACCEPT
    } else {
        VERDICT_REJECT
    };
    out
}

/// Lay out the public values with a typed object digest carried through:
/// `object_digest || statement_digest || verdict` ([`PUBLIC_VALUES_WITH_OBJECT_LEN`]).
pub fn public_values_with_object(
    object_digest: &[u8; 32],
    statement_digest: &[u8; 32],
    verdict: bool,
) -> [u8; PUBLIC_VALUES_WITH_OBJECT_LEN] {
    let mut out = [0u8; PUBLIC_VALUES_WITH_OBJECT_LEN];
    out[..32].copy_from_slice(object_digest);
    out[32..].copy_from_slice(&public_values(statement_digest, verdict));
    out
}

/// Split committed public values in either layout into
/// `(typed object digest if carried, statement digest, verdict byte)`.
pub fn split_public_values(bytes: &[u8]) -> Option<(Option<[u8; 32]>, [u8; 32], u8)> {
    match bytes.len() {
        PUBLIC_VALUES_LEN => Some((None, bytes[..32].try_into().ok()?, bytes[32])),
        PUBLIC_VALUES_WITH_OBJECT_LEN => Some((
            Some(bytes[..32].try_into().ok()?),
            bytes[32..64].try_into().ok()?,
            bytes[64],
        )),
        _ => None,
    }
}

/// Decode a verdict byte: `(verdict, unsound)`, or `None` for a byte no build commits.
pub fn decode_verdict(byte: u8) -> Option<(bool, bool)> {
    match byte {
        0 => Some((false, false)),
        1 => Some((true, false)),
        0xEE => Some((true, true)),
        0xEF => Some((false, true)),
        _ => None,
    }
}

